  chain_cells (unw_W B (bv_unsigned sp)) m bp ch ->
  rw_cells asegs m 0x225d00 [C8 (Z_to_bv 64 0x2d4560)] -> rw_cells asegs m 0x2d4560 [C8 (Z_to_bv 64 4096)] ->
  rw_cells asegs m (B + 8) [C4 szw] -> u64arr asegs m (B + 16) tb -> rw_cells asegs m (B + 2056) [C8 tfb] ->
  stk asegs m lo (bv_unsigned sp) -> (lo <= bv_unsigned sp - 64)%Z -> (bv_unsigned sp <= B)%Z -> (0x79a000 <= lo)%Z ->
  mem_inv asegs m ->
